# Generated by OrchestKit Claude Plugin
# Created: 2026-07-31

"""The verified `claude -p` invocation, and the guard that keeps it verified (plan T2.4).

Every flag here was validated by execution against `claude 2.1.220` (salvage note §1); the
five that must never appear were each measured to produce a run with **no gramps tools at
all**. That failure does not look like a harness bug from the outside — the model calls
nothing, so every assertion about the tree fails at once, and Stage 2 reports a catastrophic
docstring defect that does not exist.

Hence a guard rather than a comment, and hence a guard that checks **both** directions. The
gate hardening (B2–B4) established the rule for assertions: absence is not evidence. It holds
here too — a missing `--strict-mcp-config` connects whatever MCP servers the developer's own
settings declare, and the run then grades somebody else's tools while looking perfectly normal.

`ToolSearch` is the one built-in that must survive. In 2.1.x the MCP tools are deferred, so it
is the only path to them; disallowing it is the fifth killer and the only one that hides inside
an otherwise legitimate flag.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from pathlib import Path

from harness.docker_util import ProbeError

CLAUDE_BIN = "claude"
# Not a preference: the flag semantics below were probed against this build, and an unknown
# flag is a hard error while a *reinterpreted* one is silent. The runner records what it found.
VERIFIED_CLI_VERSION = "2.1.220"
# The canonical name from `modelUsage`, never the `sonnet` alias — an alias lets a rollover
# move the Stage-2 baseline without one line of this repo changing.
MODEL = "claude-sonnet-5"
TIMEOUT_S = 300.0

TOOL_SEARCH = "ToolSearch"
SIMPLE_MODE_ENV = "CLAUDE_CODE_SIMPLE"

SYSTEM_PROMPT = (
    "You are helping a genealogist manage their family tree with the tools provided. "
    "Act on the request directly; do not ask clarifying questions."
)

# The built-ins denied for the run. `ToolSearch` is deliberately absent; so is `mcp__*`, which
# `--disallowedTools` does not accept anyway.
DISALLOWED_TOOLS = (
    "Bash",
    "Edit",
    "Write",
    "Read",
    "Glob",
    "Grep",
    "WebFetch",
    "WebSearch",
    "Task",
    "NotebookEdit",
    "TodoWrite",
    "Skill",
    "Workflow",
    "Monitor",
    "SendMessage",
    "PushNotification",
    "RemoteTrigger",
    "DesignSync",
    "EnterWorktree",
    "ExitWorktree",
    "ReportFindings",
    "ScheduleWakeup",
    "CronCreate",
    "CronDelete",
    "CronList",
    "TaskCreate",
    "TaskGet",
    "TaskList",
    "TaskOutput",
    "TaskStop",
    "TaskUpdate",
)

# Each measured to leave the model with zero gramps tools (salvage §0, runs 1–3 and 5).
FORBIDDEN_FLAGS = ("--tools", "--safe-mode", "--bare")

# Each removes a distinct, measured source of contamination or of blindness.
REQUIRED_FLAGS = (
    "--setting-sources",
    "--disable-slash-commands",
    "--mcp-config",
    "--strict-mcp-config",
    "--permission-mode",
    "--output-format",
    "--verbose",
    "--model",
    "--no-session-persistence",
)


def build_argv(
    prompt: str,
    *,
    config: Path,
    model: str = MODEL,
    extra: Sequence[str] = (),
) -> list[str]:
    """The full argv, guarded. `extra` exists so a caller's addition is guarded too."""
    argv = [
        CLAUDE_BIN,
        "-p",
        "--setting-sources",
        "",
        "--disable-slash-commands",
        "--mcp-config",
        str(config),
        "--strict-mcp-config",
        "--permission-mode",
        "bypassPermissions",
        "--disallowedTools",
        *DISALLOWED_TOOLS,
        "--output-format",
        "stream-json",
        "--verbose",
        "--model",
        model,
        "--no-session-persistence",
        "--append-system-prompt",
        SYSTEM_PROMPT,
        *extra,
        prompt,
    ]
    assert_usable(argv, {})
    return argv


def assert_usable(argv: Sequence[str], env: Mapping[str, str]) -> None:
    """Refuse an invocation that would silently test nothing. Both directions."""
    for flag in FORBIDDEN_FLAGS:
        if any(item == flag or item.startswith(f"{flag}=") for item in argv):
            raise ProbeError(
                f"{flag} leaves the run with no gramps tools at all — the result reads as a "
                "total docstring failure and is a harness bug"
            )

    if TOOL_SEARCH in argv:
        raise ProbeError(
            f"{TOOL_SEARCH} must stay allowed: the MCP tools are deferred in "
            f"{VERIFIED_CLI_VERSION}, so it is the only path to them"
        )

    if SIMPLE_MODE_ENV in env:
        raise ProbeError(
            f"{SIMPLE_MODE_ENV} destroys the subscription login (`Not logged in`) and there is "
            "no API key to fall back on"
        )

    for flag in REQUIRED_FLAGS:
        if flag not in argv:
            raise ProbeError(f"{flag} is missing — {_why_required(flag)}")

    _assert_model_is_canonical(argv)


def run_env(base: Mapping[str, str]) -> dict[str, str]:
    """The child's environment: the subscription login in `~/.claude` stays, the killer goes.

    Only the one variable that is never legitimately set for such a run is removed here.
    Everything else is checked where it is *observable* instead of guessed at: an inherited
    `ANTHROPIC_API_KEY` would silently move the run off the subscription, and the `init` event
    reports `apiKeySource`, so the self-check reads the fact rather than the environment.
    """
    return {key: value for key, value in base.items() if key != SIMPLE_MODE_ENV}


def assert_clean_cwd(cwd: Path) -> None:
    """The run's working directory must hold nothing — `CLAUDE.md`, `.mcp.json` and `.claude/`
    are all discovered from it, and each is exactly the contamination `--setting-sources ""`
    was chosen to remove."""
    found = sorted(path.name for path in cwd.iterdir())
    if found:
        raise ProbeError(
            f"the Stage-2 working directory {cwd} is not empty (found: {', '.join(found)}) — "
            "anything discovered from it steers the model under test"
        )


def _assert_model_is_canonical(argv: Sequence[str]) -> None:
    value = argv[argv.index("--model") + 1]
    if not value.startswith("claude-"):
        raise ProbeError(
            f"--model {value!r} is an alias — pin the canonical name ({MODEL}) so a model "
            "rollover cannot move the Stage-2 baseline silently"
        )


def _why_required(flag: str) -> str:
    return {
        "--setting-sources": "the user's settings bring hooks, plugins, skills and a global "
        "CLAUDE.md into the run",
        "--disable-slash-commands": "belt and braces on the skill surface",
        "--mcp-config": "without it the run has no gramps server at all",
        "--strict-mcp-config": "without it the developer's own MCP servers leak in and get graded",
        "--permission-mode": "an unattended run cannot answer a permission prompt",
        "--output-format": "stream-json is the wire log this suite grades",
        "--verbose": "stream-json under -p emits nothing without it",
        "--model": "an unpinned model moves the baseline between runs",
        "--no-session-persistence": "a persisted session writes into ~/.claude/projects",
    }[flag]
